function renderInitialAudienceFields(): string {
  const fields = renderAudienceFields().replace('name="entry_slug"', 'name="entry_slug" required');
  return `<div class="initial-audience-fields">${fields}</div>`;
}
function renderCreateDetails(): string {
  const infoIcon = `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"></circle><path d="M12 10.5v5M12 7.5h.01"></path></svg>`;
  const card = (id: string, kind: string, title: string, info: string, body: string) => `<section id="${id}" class="condition-card" data-condition-card="${kind}"><div class="condition-card-header"><label class="condition-card-title" for="${kind}_enabled"><strong>${title}</strong><span data-condition-state="${kind}">未設定</span></label><span class="condition-info-wrap"><button class="condition-info" type="button" data-condition-info="${kind}" aria-controls="${kind}_info" aria-expanded="false" aria-label="${title}の説明を表示">${infoIcon}</button><span id="${kind}_info" class="condition-tooltip" role="tooltip" hidden>${info}</span></span><label class="condition-switch"><input id="${kind}_enabled" type="checkbox" data-condition-toggle aria-controls="${kind}_fields"><span aria-hidden="true"></span></label></div><div id="${kind}_fields" class="condition-card-body" data-condition-body hidden>${body}</div></section>`;
  const period = card("create-condition-expiry", "period", "利用できる期間", "開始または終了の日時を設定します。", `<div class="condition-card-grid"><div class="condition-card-field"><label for="unlock_at">開始日時</label>${localDatetimeInput("unlock_at", "unlock_at", null, false)}</div><div class="condition-card-field"><label for="expires_at">終了日時</label>${localDatetimeInput("expires_at", "expires_at", null, false)}</div></div>`);
  const usage = card("create-condition-limit", "limit", "回数制限", "通常アクセスの回数を制限します。", `<div class="condition-card-grid"><div class="condition-card-field"><label for="max_open_count">上限回数</label><input id="max_open_count" type="number" name="max_open_count" min="1" max="${MAX_OPEN_COUNT}" step="1" inputmode="numeric" placeholder="例: 1,000"></div><div class="condition-card-field"><label for="limit_reached_action">上限到達後の動作</label><select id="limit_reached_action" class="condition-card-select" data-limit-reached-action><option value="end">リンクを終了</option><option value="redirect">別のURLへ転送</option></select></div><div id="limit_reached_target_fields" data-limit-fallback-fields hidden><input id="limit_reached_target_enabled" class="condition-contract-checkbox" type="checkbox" name="limit_reached_target_enabled" value="1" tabindex="-1" aria-hidden="true"><label for="limit_reached_target_url">転送先URL</label><input id="limit_reached_target_url" type="url" name="limit_reached_target_url" placeholder="https://example.com/after-limit" maxlength="2048" autocomplete="url"></div></div>`);
  const redirects = card("create-condition-schedule", "schedule", "日時で転送先を変更", "指定日時から別のURLへ転送します。", `<div class="condition-card-grid"><div class="condition-card-field"><label for="switch_at">切替日時</label>${localDatetimeInput("switch_at", "switch_at", null, false)}</div><div class="condition-card-field"><label for="scheduled_target_url">切替後の転送先URL</label><input id="scheduled_target_url" type="url" name="scheduled_target_url" placeholder="https://example.com/new" maxlength="2048" autocomplete="url"></div></div>`);
  const protection = card("create-condition-protection", "protection", "合言葉で保護", "合言葉を知る人だけが開けます。", `<div class="condition-card-field"><label for="passphrase">合言葉</label>${passphraseInput("passphrase", "new-password")}</div>`);
  const endDisplay = card("create-condition-end-display", "end-display", "終了時の表示", "期限切れや上限到達時に表示する案内です。", renderTerminalMessageFields(undefined, true));
  const preview = card("create-condition-preview", "preview", "SNSプレビュー", "共有時に表示する内容を設定します。", renderPreviewFields(undefined, true));
  const audience = card("create-condition-audience", "audience", "相手別入口", "相手や用途ごとの入口URLを1つ作成します。", renderInitialAudienceFields());
  return `<details class="create-settings"><summary id="create-settings-title">設定（任意）</summary><div class="condition-list">${period}${usage}${redirects}${protection}${endDisplay}${preview}${audience}</div></details>`;
}
function renderCreateQueryPresetScript(): string {
  return `<script>(()=>{
    const apply=()=>{
      const form=document.querySelector("form.create-form[data-query-preset]");
      if(!(form instanceof HTMLFormElement))return;
      const params=new URLSearchParams(location.search);
      if(params.get("restore")==="1")return;
      const values={target_url:null,custom_slug:null,word_slug_enabled:null,unlock_at:null,expires_at:null,max_open_count:null,limit_reached_action:new Set(["end","redirect"]),limit_reached_target_url:null,switch_at:null,scheduled_target_url:null,ended_message:null,preview_mode:new Set(["none","target_og","custom","target_url"]),og_title:null,og_description:null,og_image_url:null,entry_label:null,entry_slug:null,entry_expires_at:null,entry_ended_message:null,entry_preview_mode:new Set(["none","target_og","custom","target_url"]),entry_og_title:null,entry_og_description:null,entry_og_image_url:null};
      const setValue=(name,allowed)=>{
        const value=params.get(name);
        if(value===null||(allowed instanceof Set&&!allowed.has(value)))return false;
        const selector='input[name="'+name+'"],select[name="'+name+'"],textarea[name="'+name+'"]'+(name==="limit_reached_action"?",#limit_reached_action":"");
        const controls=[...form.querySelectorAll(selector)];
        if(!controls.length)return false;
        const first=controls[0];
        if(first instanceof HTMLInputElement&&first.type==="checkbox"){first.checked=value==="1"||value==="true";return true}
        if(first instanceof HTMLInputElement&&first.type==="radio"){for(const control of controls)if(control instanceof HTMLInputElement)control.checked=control.value===value;return true}
        if(first instanceof HTMLSelectElement&&!Array.from(first.options).some(option=>option.value===value))return false;
        for(const control of controls)if(control instanceof HTMLInputElement||control instanceof HTMLSelectElement||control instanceof HTMLTextAreaElement)control.value=value;
        return true;
      };
      const changed=new Set;
      for(const [name,allowed] of Object.entries(values))if(setValue(name,allowed))changed.add(name);
      const conditionFields={period:["unlock_at","expires_at"],limit:["max_open_count","limit_reached_action","limit_reached_target_url"],schedule:["switch_at","scheduled_target_url"],protection:[],"end-display":["ended_message"],preview:["preview_mode","og_title","og_description","og_image_url"],audience:["entry_label","entry_slug","entry_expires_at","entry_ended_message","entry_preview_mode","entry_og_title","entry_og_description","entry_og_image_url"]};
      let opened=false;
      for(const [kind,fields] of Object.entries(conditionFields)){
        const toggle=document.getElementById(kind+"_enabled"),explicit=params.get(kind+"_enabled");
        if(!(toggle instanceof HTMLInputElement))continue;
        const enabled=explicit===null?fields.some(name=>changed.has(name)):(explicit==="1"||explicit==="true");
        if(explicit!==null||enabled){toggle.checked=enabled;toggle.dispatchEvent(new Event("change",{bubbles:true}));opened=opened||enabled}
      }
      if(changed.has("word_slug_enabled")){const word=form.elements.namedItem("word_slug_enabled");if(word instanceof HTMLInputElement)word.dispatchEvent(new Event("change",{bubbles:true}))}
      if(opened){const details=form.querySelector(".create-settings");if(details instanceof HTMLDetailsElement)details.open=true}
      form.dispatchEvent(new Event("input",{bubbles:true}));
      form.dispatchEvent(new Event("change",{bubbles:true}));
    };
    if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",apply,{once:true});else apply();
  })();</script>`;
}
