function createErrorFocus(message: string): string { if (message.includes("OG情報") || message.includes("SNSプレビュー") || message.includes("指定プレビュー") || message.includes("プレビュー画像")) return "create-condition-preview"; if (message.includes("短縮パス")) return "custom_slug"; if (message.includes("利用回数") || message.includes("上限到達後")) return "create-condition-limit"; if (message.includes("切替")) return "create-condition-schedule"; if (message.includes("開始日時") || message.includes("共有期限")) return "create-condition-expiry"; if (message.includes("合言葉")) return "create-condition-protection"; if (message.includes("入口")) return "create-condition-audience"; return "target_url"; }
function renderCreateErrorPage(message: string, focus = createErrorFocus(message)): Response { const query = new URLSearchParams({ restore: "1", error: message, focus }); const hash = focus ? `#${encodeURIComponent(focus)}` : ""; return renderLayout("設定を変更", `<section class="card"><h1>設定を確認してください</h1><div class="error" role="alert"><strong>作成できませんでした</strong><p>${escapeHtml(message)}</p></div><p class="hint">入力済みの設定は保持されています。内容を確認してから、もう一度作成してください。</p><p><a class="button secondary" href="/?${query.toString()}${hash}">設定を変更</a></p></section>`, 400); }

function isPreviewRequest(request: Request): boolean {
  if (new URL(request.url).searchParams.get("preview") === "og") return true;
  const purpose = `${request.headers.get("Purpose") ?? ""} ${request.headers.get("Sec-Purpose") ?? ""} ${request.headers.get("X-Purpose") ?? ""}`;
  if (/preview|prefetch|prerender/i.test(purpose)) return true;
  const userAgent = request.headers.get("User-Agent") ?? "";
  return /facebookexternalhit|facebot|twitterbot|linkedinbot|slackbot|discordbot|telegrambot|whatsapp|pinterestbot|redditbot|googlebot|google-pagerenderer|googledocs|bingbot|applebot|skypeuripreview|msteams|microsoft\s+teams/i.test(userAgent);
}
function appendOgAttribution(description: string): string { return `${description}\n\n${OG_ATTRIBUTION}`; }
function renderPreviewUnavailable(): Response {
  const description = appendOgAttribution("この短縮リンクは現在プレビューを表示できません。");
  return htmlResponse(`<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(OG_SITE_NAME)}</title><meta property="og:type" content="website"><meta property="og:site_name" content="${escapeHtml(OG_SITE_NAME)}"><meta property="og:description" content="${escapeHtml(description)}"><meta name="twitter:card" content="summary"><meta name="twitter:description" content="${escapeHtml(description)}"></head><body><p>${escapeHtml(OG_SITE_NAME)}</p><p>${escapeHtml(description)}</p></body></html>`);
}
function renderOgPreview(request: Request, target: PublicTarget): Response {
  const { link, entry, slug } = target; const previewMode = entry?.preview_mode ?? link.preview_mode;
  const destination = activeDestination(link);
  const snapshot = previewMode === "target_url"
    ? { title: `リンク先: ${destination}`, description: destination, imageUrl: null }
    : entry ? { title: entry.og_title, description: entry.og_description, imageUrl: entry.og_image_url } : { title: link.og_title, description: link.og_description, imageUrl: link.og_image_url };
  const title = snapshot.title || "短縮リンク";
  const description = appendOgAttribution(snapshot.description || "この短縮リンクの転送先を開きます。");
  const image = snapshot.imageUrl ? `<meta property="og:image" content="${escapeHtml(snapshot.imageUrl)}"><meta name="twitter:image" content="${escapeHtml(snapshot.imageUrl)}">` : "";
  const shortUrl = buildShortUrl(request, slug);
  return htmlResponse(`<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(title)}</title><meta property="og:type" content="website"><meta property="og:url" content="${escapeHtml(shortUrl)}"><meta property="og:site_name" content="${escapeHtml(OG_SITE_NAME)}"><meta property="og:title" content="${escapeHtml(title)}"><meta property="og:description" content="${escapeHtml(description)}"><meta name="twitter:card" content="${snapshot.imageUrl ? "summary_large_image" : "summary"}"><meta name="twitter:title" content="${escapeHtml(title)}"><meta name="twitter:description" content="${escapeHtml(description)}">${image}</head><body><h1>${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p><p>${escapeHtml(OG_SITE_NAME)}</p></body></html>`);
}

async function verifyTurnstile(token: string | null, request: Request, env: Env): Promise<boolean> {
  const expectedHostnames = new Set((env.TURNSTILE_HOSTNAMES ?? "").split(",").map((hostname) => hostname.trim().toLowerCase()).filter(Boolean));
  if (!env.TURNSTILE_SECRET || !token || token.length > MAX_TURNSTILE_TOKEN_LENGTH || expectedHostnames.size === 0) return false;
  const body = new URLSearchParams({ secret: env.TURNSTILE_SECRET, response: token }); const remoteIp = request.headers.get("CF-Connecting-IP"); if (remoteIp) body.set("remoteip", remoteIp);
  try { const response = await fetch(TURNSTILE_VERIFY_URL, { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body, signal: AbortSignal.timeout(10_000) }); if (!response.ok) return false; const result = await response.json() as TurnstileVerifyResponse; return result.success === true && result.action === TURNSTILE_ACTION && typeof result.hostname === "string" && expectedHostnames.has(result.hostname.toLowerCase()); } catch { return false; }
}
async function createPassphraseRecord(passphrase: string): Promise<PassphraseRecord> { const salt = crypto.getRandomValues(new Uint8Array(16)); const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(passphrase), "PBKDF2", false, ["deriveBits"]); const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: PASSPHRASE_ITERATIONS }, key, 256); return { salt: base64UrlEncode(salt), hash: base64UrlEncode(new Uint8Array(bits)), iterations: PASSPHRASE_ITERATIONS }; }
async function matchesPassphrase(link: Link, passphrase: string): Promise<boolean> { if (!link.passphrase_hash || !link.passphrase_salt || !link.passphrase_iterations) return false; const salt = base64UrlDecode(link.passphrase_salt); const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(passphrase), "PBKDF2", false, ["deriveBits"]); const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: link.passphrase_iterations }, key, 256); return timingSafeStringEqual(base64UrlEncode(new Uint8Array(bits)), link.passphrase_hash); }
function audienceInsertStatement(env: Env, audience: AudienceValues, parentSlug: string, manageKey: string): D1PreparedStatement {
  return env.DB.prepare(`INSERT INTO audience_entries (parent_link_id,slug,label,expires_at,ended_message,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url) SELECT id,?,?,?,?,?,?,?,?,?,?,? FROM links WHERE slug=? AND manage_key=? AND deleted_at IS NULL`).bind(audience.slug, audience.label, audience.expiresAt, audience.endedMessage, audience.shareCardEnabled ? 1 : 0, audience.shareCardTitle, audience.shareCardDescription, audience.previewMode, audience.ogTitle, audience.ogDescription, audience.ogImageUrl, parentSlug, manageKey);
}
async function createLink(env: Env, values: CreateValues, initialAudiences: AudienceValues[] = []): Promise<Link> {
  const manageKey = generateManageKey();
  const insert = async (slug: string): Promise<Link> => {
    if (initialAudiences.length) {
      await env.DB.batch([linkInsertStatement(env, slug, manageKey, values), ...initialAudiences.map((audience) => audienceInsertStatement(env, audience, slug, manageKey))]);
    } else {
      await linkInsertStatement(env, slug, manageKey, values).run();
    }
    const created = await getLinkBySlug(env, slug); if (!created) throw new Error("Created link was not found"); return created;
  };
  if (values.slug) {
    try { return await insert(values.slug); } catch (error) { if (isUniqueConstraintError(error)) throw new SlugUnavailableError(); throw error; }
  }
  for (let attempt = 0; attempt < MAX_SLUG_ATTEMPTS; attempt += 1) {
    const slug = generateSlug();
    try { return await insert(slug); } catch (error) {
      if (!isUniqueConstraintError(error)) throw error;
      if (initialAudiences.length && await Promise.all(initialAudiences.map((audience) => isIssuedSlug(env, audience.slug))).then((issued) => issued.some(Boolean))) throw new SlugUnavailableError();
    }
  }
  throw new SlugUnavailableError();
}
function spokenAudienceEntries(slugs: SpokenSlugSet): AudienceValues[] {
  return [
    ["hiragana", "ひらがな"], ["katakana", "カタカナ"], ["kanji", "漢字"],
  ].map(([notation, label]) => ({ slug: slugs[notation as keyof SpokenSlugSet], label: `${label}表記`, expiresAt: null, endedMessage: null, shareCardEnabled: false, shareCardTitle: null, shareCardDescription: null, previewMode: "none", ogTitle: null, ogDescription: null, ogImageUrl: null }));
}
interface CreatedLink { link: Link; spokenSlugs: SpokenSlugSet | null; }
async function createConfiguredLink(env: Env, values: CreateValues, initialAudiences: AudienceValues[] = []): Promise<CreatedLink> {
  if (values.slugStyle !== "words-ja") return { link: await createLink(env, values, initialAudiences), spokenSlugs: null };
  if (values.slug) throw new Error("Word slugs cannot be combined with a custom slug");
  for (let attempt = 0; attempt < MAX_SLUG_ATTEMPTS; attempt += 1) {
    const spokenSlugs = generateSpokenSlugSet();
    try {
      const link = await createLink(env, { ...values, slug: spokenSlugs.romaji, slugStyle: "random" }, [...initialAudiences, ...spokenAudienceEntries(spokenSlugs)]);
      return { link, spokenSlugs };
    } catch (error) { if (!(error instanceof SlugUnavailableError)) throw error; }
  }
  throw new SlugUnavailableError();
}
interface CreateValues { slug?: string; slugStyle: SlugStyle; targetUrl: string; maxOpenCount: number | null; limitReachedTargetUrl: string | null; scheduledTargetUrl: string | null; switchAt: string | null; unlockAt: string | null; expiresAt: string | null; endedMessage: string | null; receiptRequired: boolean; passphrase: PassphraseRecord | null; shareCardEnabled: boolean; shareCardTitle: string | null; shareCardDescription: string | null; previewMode?: PreviewMode; ogTitle?: string | null; ogDescription?: string | null; ogImageUrl?: string | null; }
function linkInsertStatement(env: Env, slug: string, manageKey: string, values: CreateValues): D1PreparedStatement { return env.DB.prepare(`INSERT INTO links (slug,target_url,manage_key,one_time,max_open_count,open_count,limit_reached_target_url,scheduled_target_url,switch_at,unlock_at,expires_at,ended_message,receipt_required,passphrase_salt,passphrase_hash,passphrase_iterations,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(slug, values.targetUrl, manageKey, values.maxOpenCount === 1 ? 1 : 0, values.maxOpenCount, 0, values.limitReachedTargetUrl, values.scheduledTargetUrl, values.switchAt, values.unlockAt, values.expiresAt, values.endedMessage, values.receiptRequired ? 1 : 0, values.passphrase?.salt ?? null, values.passphrase?.hash ?? null, values.passphrase?.iterations ?? null, values.shareCardEnabled ? 1 : 0, values.shareCardTitle, values.shareCardDescription, values.previewMode ?? "none", values.ogTitle ?? null, values.ogDescription ?? null, values.ogImageUrl ?? null); }
async function isIssuedSlug(env: Env, slug: string): Promise<boolean> { return Boolean(await env.DB.prepare("SELECT 1 FROM issued_slugs WHERE slug=? LIMIT 1").bind(slug).first()); }
async function getLinkBySlug(env: Env, slug: string): Promise<Link | null> { return env.DB.prepare(`SELECT id,slug,target_url,manage_key,one_time,used_at,max_open_count,open_count,limit_reached_target_url,scheduled_target_url,switch_at,unlock_at,expires_at,ended_message,receipt_required,receipt_confirmed_at,passphrase_salt,passphrase_hash,passphrase_iterations,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url,state_version,created_at,updated_at,deleted_at,admin_paused_at FROM links WHERE slug=? AND deleted_at IS NULL AND admin_paused_at IS NULL LIMIT 1`).bind(slug).first<Link>(); }
async function getManageLink(env: Env, slug: string, key: string): Promise<Link | null> { const link = await getLinkBySlug(env, slug); return link && await timingSafeStringEqual(key, link.manage_key) ? link : null; }
const audienceColumns = "id,parent_link_id,slug,label,expires_at,ended_message,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url,state_version,created_at,updated_at,deleted_at";
async function getAudienceEntries(env: Env, parentLinkId: number): Promise<AudienceEntry[]> { const result = await env.DB.prepare(`SELECT ${audienceColumns} FROM audience_entries WHERE parent_link_id=? AND deleted_at IS NULL ORDER BY created_at ASC,id ASC`).bind(parentLinkId).all<AudienceEntry>(); return result.results; }
async function getAudienceEntry(env: Env, parentLinkId: number, id: number): Promise<AudienceEntry | null> { return env.DB.prepare(`SELECT ${audienceColumns} FROM audience_entries WHERE id=? AND parent_link_id=? AND deleted_at IS NULL LIMIT 1`).bind(id, parentLinkId).first<AudienceEntry>(); }
async function getAudiencePublicTarget(env: Env, slug: string): Promise<PublicTarget | null> {
  const row = await env.DB.prepare(`SELECT l.id AS parent_id,l.slug AS parent_slug,l.target_url,l.manage_key,l.one_time,l.used_at,l.max_open_count,l.open_count,l.limit_reached_target_url,l.scheduled_target_url,l.switch_at,l.unlock_at,l.expires_at AS parent_expires_at,l.ended_message AS parent_ended_message,l.receipt_required,l.receipt_confirmed_at,l.passphrase_salt,l.passphrase_hash,l.passphrase_iterations,l.share_card_enabled AS parent_share_card_enabled,l.share_card_title AS parent_share_card_title,l.share_card_description AS parent_share_card_description,l.preview_mode AS parent_preview_mode,l.og_title AS parent_og_title,l.og_description AS parent_og_description,l.og_image_url AS parent_og_image_url,l.state_version AS parent_state_version,l.created_at AS parent_created_at,l.updated_at AS parent_updated_at,l.deleted_at AS parent_deleted_at,l.admin_paused_at AS parent_admin_paused_at,e.id AS entry_id,e.slug AS entry_slug,e.label,e.expires_at,e.ended_message,e.share_card_enabled AS entry_share_card_enabled,e.share_card_title AS entry_share_card_title,e.share_card_description AS entry_share_card_description,e.preview_mode AS entry_preview_mode,e.og_title AS entry_og_title,e.og_description AS entry_og_description,e.og_image_url AS entry_og_image_url,e.state_version AS entry_state_version,e.created_at AS entry_created_at,e.updated_at AS entry_updated_at,e.deleted_at AS entry_deleted_at FROM audience_entries e JOIN links l ON l.id=e.parent_link_id WHERE e.slug=? AND e.deleted_at IS NULL AND l.deleted_at IS NULL AND l.admin_paused_at IS NULL LIMIT 1`).bind(slug).first<Record<string, unknown>>();
  if (!row) return null;
  const link: Link = { id: Number(row.parent_id), slug: String(row.parent_slug), target_url: String(row.target_url), manage_key: String(row.manage_key), one_time: Number(row.one_time), used_at: row.used_at as string | null, max_open_count: row.max_open_count as number | null, open_count: Number(row.open_count), limit_reached_target_url: row.limit_reached_target_url as string | null, scheduled_target_url: row.scheduled_target_url as string | null, switch_at: row.switch_at as string | null, unlock_at: row.unlock_at as string | null, expires_at: row.parent_expires_at as string | null, ended_message: row.parent_ended_message as string | null, receipt_required: Number(row.receipt_required), receipt_confirmed_at: row.receipt_confirmed_at as string | null, passphrase_salt: row.passphrase_salt as string | null, passphrase_hash: row.passphrase_hash as string | null, passphrase_iterations: row.passphrase_iterations as number | null, share_card_enabled: Number(row.parent_share_card_enabled), share_card_title: row.parent_share_card_title as string | null, share_card_description: row.parent_share_card_description as string | null, preview_mode: row.parent_preview_mode as PreviewMode, og_title: row.parent_og_title as string | null, og_description: row.parent_og_description as string | null, og_image_url: row.parent_og_image_url as string | null, state_version: Number(row.parent_state_version), created_at: String(row.parent_created_at), updated_at: row.parent_updated_at as string | null, deleted_at: row.parent_deleted_at as string | null, admin_paused_at: row.parent_admin_paused_at as string | null };
  const entry: AudienceEntry = { id: Number(row.entry_id), parent_link_id: link.id, slug: String(row.entry_slug), label: String(row.label), expires_at: row.expires_at as string | null, ended_message: row.ended_message as string | null, share_card_enabled: Number(row.entry_share_card_enabled), share_card_title: row.entry_share_card_title as string | null, share_card_description: row.entry_share_card_description as string | null, preview_mode: row.entry_preview_mode as PreviewMode, og_title: row.entry_og_title as string | null, og_description: row.entry_og_description as string | null, og_image_url: row.entry_og_image_url as string | null, state_version: Number(row.entry_state_version), created_at: String(row.entry_created_at), updated_at: row.entry_updated_at as string | null, deleted_at: row.entry_deleted_at as string | null };
  return { link, entry, slug };
}

function renderExtensionCreate(env: Env): Response {
  const turnstile = env.TURNSTILE_SITE_KEY ? `<script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script><div class="cf-turnstile" data-sitekey="${escapeHtml(env.TURNSTILE_SITE_KEY)}" data-action="${TURNSTILE_ACTION}" data-size="invisible" data-callback="goExtensionTurnstile" data-expired-callback="goExtensionTurnstileError" data-error-callback="goExtensionTurnstileError"></div>` : "";
  const document = `<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;font:13px system-ui,sans-serif;color:#4c3926;background:transparent}.cf-turnstile{min-height:65px}.message{margin:0 0 8px}</style></head><body><p class="message" aria-live="polite">安全確認中…</p>${turnstile}<script>(()=>{let targetUrl="";const extensionOrigin=${JSON.stringify(EXTENSION_ORIGIN)},tell=(type,detail={})=>parent.postMessage({source:"go-extension-create",type,...detail},extensionOrigin);window.goExtensionTurnstile=token=>{if(targetUrl&&typeof token==="string")tell("token",{targetUrl,turnstileToken:token})};window.goExtensionTurnstileError=()=>tell("error",{message:"安全確認を完了できませんでした。"});window.addEventListener("message",event=>{if(event.origin!==extensionOrigin||event.source!==parent||!event.data||event.data.source!=="go-extension-popup")return;const value=typeof event.data.targetUrl==="string"?event.data.targetUrl:"";if(!value){tell("error",{message:"URLを取得できませんでした。"});return}targetUrl=value});tell("ready")})()</script></body></html>`;
  return new Response(document, { headers: extensionHtmlHeaders(Boolean(turnstile)) });
}
async function handleExtensionCreate(request: Request, env: Env): Promise<Response> {
  let payload: { targetUrl?: unknown; turnstileToken?: unknown }; try { payload = await request.json(); } catch { return jsonResponse({ error: "リクエストを読み取れませんでした。" }, 400); }
  const targetUrl = typeof payload.targetUrl === "string" ? payload.targetUrl : ""; const token = typeof payload.turnstileToken === "string" ? payload.turnstileToken : null;
  if (request.headers.get("Origin") !== EXTENSION_ORIGIN) return jsonResponse({ error: "この拡張機能からのみ作成できます。" }, 403);
  if (!(await verifyTurnstile(token, request, env))) return jsonResponse({ error: "安全確認に失敗しました。" }, 403);
  const target = isValidTargetUrl(targetUrl.trim(), new URL(request.url)); if (!target.ok) return jsonResponse({ error: "有効なURLを入力してください。" }, 400);
  const values: CreateValues = { slugStyle: "random", targetUrl: target.url, maxOpenCount: null, limitReachedTargetUrl: null, scheduledTargetUrl: null, switchAt: null, unlockAt: null, expiresAt: null, endedMessage: null, receiptRequired: false, passphrase: null, shareCardEnabled: false, shareCardTitle: null, shareCardDescription: null, previewMode: "none", ogTitle: null, ogDescription: null, ogImageUrl: null };
  try { const link = await createLink(env, values); const shortUrl = buildShortUrl(request, link.slug); return jsonResponse({ shortUrl, manageUrl: buildManageUrl(request, link.slug, link.manage_key), qrSvg: qrSvg(shortUrl) }, 201); } catch (error) { if (error instanceof SlugUnavailableError) return jsonResponse({ error: "短縮URLを作成できませんでした。もう一度お試しください。" }, 409); throw error; }
}
async function handleHome(request: Request, env: Env): Promise<Response> { const error = new URL(request.url).searchParams.get("error") ?? undefined; return renderHome(request, env, error); }

async function requireAdmin(request: Request, env: Env): Promise<AdminIdentity | Response> {
  const teamDomain = env.ACCESS_TEAM_DOMAIN?.trim().replace(/^https:\/\//, "").replace(/\/+$/, "");
  const audiences = (env.ACCESS_ADMIN_AUDS ?? "").split(",").map((value) => value.trim()).filter(Boolean);
  const token = request.headers.get("Cf-Access-Jwt-Assertion");
  if (!teamDomain || !audiences.length || !token) return renderErrorPage(403, "Forbidden", "管理者認証を確認できません。");
  const issuer = `https://${teamDomain}`;
  let jwks = accessJwks.get(issuer);
  if (!jwks) { jwks = createRemoteJWKSet(new URL(`${issuer}/cdn-cgi/access/certs`)); accessJwks.set(issuer, jwks); }
  try {
    const { payload } = await jwtVerify(token, jwks, { issuer, audience: audiences, algorithms: ["RS256"] });
    if (typeof payload.sub !== "string" || !payload.sub) throw new Error("Access token is missing subject");
    return { subject: payload.sub, email: typeof payload.email === "string" ? payload.email : null };
  } catch {
    return renderErrorPage(403, "Forbidden", "管理者認証を確認できません。");
  }
}

function requireAdminMutation(request: Request): Response | null {
  return request.method === "POST" ? null : renderErrorPage(405, "Method Not Allowed", "この操作は許可されていません。", "POST");
}

async function writeAdminAudit(env: Env, admin: AdminIdentity, action: string, link: Link | null, detail: string | null = null): Promise<void> {
  await env.DB.prepare("INSERT INTO admin_audit_events (actor_subject,actor_email,action,link_id,link_slug,detail) VALUES (?,?,?,?,?,?)")
    .bind(admin.subject, admin.email, action, link?.id ?? null, link?.slug ?? null, detail).run();
}

async function getAdminLinkBySlug(env: Env, slug: string): Promise<Link | null> {
  return env.DB.prepare("SELECT * FROM links WHERE slug=? LIMIT 1").bind(slug).first<Link>();
}

