async function handleSlugAvailability(request: Request, env: Env): Promise<Response> { const slug = normalizeSlugInput(new URL(request.url).searchParams.get("slug") ?? ""); if (!isValidSlug(slug)) return jsonResponse({ available: false, message: "使えない短縮パスです。" }); const issued = await env.DB.prepare("SELECT 1 FROM issued_slugs WHERE slug = ? LIMIT 1").bind(slug).first(); return jsonResponse(issued ? { available: false, message: "この短縮パスは使用できません。" } : { available: true, message: "この短縮パスは使用できます。" }); }
async function handleCreate(request: Request, env: Env): Promise<Response> {
  const form = await request.formData();
  if (!(await verifyTurnstile(getNullableFormText(form, "cf-turnstile-response"), request, env))) return renderCreateErrorPage("認証に失敗しました。もう一度試してください。", "");
  const parsed = await parseLinkValues(form, request, true); if ("error" in parsed) return renderCreateErrorPage(parsed.error);
  const initialAudience = hasInitialAudienceValues(form) ? await parseAudienceValues(form, request, parsed.values.targetUrl, isScheduledTargetConfigured(parsed.values.scheduledTargetUrl, parsed.values.switchAt)) : null;
  if (initialAudience && "error" in initialAudience) return renderCreateErrorPage(initialAudience.error);
  try {
    const created = await createConfiguredLink(env, parsed.values, initialAudience ? [initialAudience.values] : []);
    const link = created.link;
    const alternateUrls = created.spokenSlugs ? [
      ["ひらがな", buildShortUrl(request, created.spokenSlugs.hiragana)],
      ["カタカナ", buildShortUrl(request, created.spokenSlugs.katakana)],
      ["漢字", buildShortUrl(request, created.spokenSlugs.kanji)],
    ] as const : [];
    return renderCreatedPage(buildShortUrl(request, link.slug), buildManageUrl(request, link.slug, link.manage_key), link, alternateUrls);
  } catch (error) { if (error instanceof SlugUnavailableError) return renderCreateErrorPage("この短縮パスはすでに使われています。"); throw error; }
}

async function handlePublicGet(request: Request, env: Env, slug: string): Promise<Response> {
  const target = await requirePublicTarget(env, slug); if (target instanceof Response) return target;
  const { link, entry } = target; const previewMode = isScheduledTargetConfigured(link.scheduled_target_url, link.switch_at) ? "none" : (entry?.preview_mode ?? link.preview_mode);
  if (isPreviewRequest(request)) { if (isOpenLimitReached(link)) return renderTerminalUnavailable(terminalMessageFor(target)); if (previewMode === "none" || isLocked(link) || Boolean(link.passphrase_hash)) return renderPreviewUnavailable(); return renderOgPreview(request, target); }
  if (isLocked(link)) return renderLockedPage(link.unlock_at!);
  if (link.passphrase_hash && !(await hasUnlockCookie(request, target))) return renderPassphrasePage(target);
  if (isOpenLimitReached(link)) return renderLimitReachedResponse(target);
  return consumeOpenAndRedirect(request, env, target);
}
async function handleUnlock(request: Request, env: Env, slug: string): Promise<Response> {
  const target = await requirePublicTarget(env, slug); if (target instanceof Response) return target; const { link } = target;
  if (isLocked(link)) return renderLockedPage(link.unlock_at!);
  const passphrase = getFormText(await request.formData(), "passphrase");
  if (!passphrase || !(await matchesPassphrase(link, passphrase))) return renderPassphrasePage(target, "合言葉が正しくありません。");
  const expiresAt = Math.floor(Date.now() / 1000) + UNLOCK_COOKIE_SECONDS; const token = await makeUnlockToken(target, expiresAt); const headers = new Headers();
  headers.append("Set-Cookie", `${unlockCookieName(target.slug)}=${token}; Max-Age=${UNLOCK_COOKIE_SECONDS}; Path=/; HttpOnly; SameSite=Lax${new URL(request.url).protocol === "https:" ? "; Secure" : ""}`);
  return redirectResponse(buildShortUrl(request, target.slug), headers);
}
async function consumeOpenAndRedirect(request: Request, env: Env, initialTarget: PublicTarget): Promise<Response> {
  let target = initialTarget;
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const { link, entry } = target;
    if (isLocked(link)) return renderLockedPage(link.unlock_at!);
    if (link.passphrase_hash && !(await hasUnlockCookie(request, target))) return renderPassphrasePage(target);
    if (isOpenLimitReached(link)) return renderLimitReachedResponse(target);
    const destinationKind = activeDestinationKind(link);
    if (!hasOpenLimit(link)) return redirectResponse(destinationForKind(link, destinationKind));
    const opened = await env.DB.prepare(`UPDATE links SET open_count=open_count+1,used_at=CASE WHEN open_count+1>=max_open_count THEN CURRENT_TIMESTAMP ELSE used_at END WHERE id=? AND deleted_at IS NULL AND state_version=? AND (expires_at IS NULL OR julianday(expires_at)>julianday(?)) AND open_count<max_open_count AND (? IS NULL OR EXISTS (SELECT 1 FROM audience_entries WHERE id=? AND parent_link_id=links.id AND deleted_at IS NULL AND state_version=? AND (expires_at IS NULL OR julianday(expires_at)>julianday(?)))) RETURNING id,slug,target_url,manage_key,one_time,used_at,max_open_count,open_count,limit_reached_target_url,scheduled_target_url,switch_at,unlock_at,expires_at,ended_message,receipt_required,receipt_confirmed_at,passphrase_salt,passphrase_hash,passphrase_iterations,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url,state_version,created_at,updated_at,deleted_at`).bind(link.id, link.state_version, new Date().toISOString(), entry?.id ?? null, entry?.id ?? null, entry?.state_version ?? null, new Date().toISOString()).first<Link>();
    if (opened) return redirectResponse(destinationForKind(opened, destinationKind));
    const refreshed = await requirePublicTarget(env, target.slug); if (refreshed instanceof Response) return refreshed; target = refreshed;
  }
  return renderErrorPage(409, "Conflict", "リンク設定が更新されました。もう一度開いてください。");
}
async function requirePublicTarget(env: Env, slug: string): Promise<PublicTarget | Response> {
  if (!isValidSlug(slug)) return renderErrorPage(404, "Not Found", "この短縮URLは存在しません。");
  const link = await getLinkBySlug(env, slug); if (link) return isLinkExpired(link) ? renderTerminalUnavailable(link.ended_message) : { link, entry: null, slug };
  const entryTarget = await getAudiencePublicTarget(env, slug); if (!entryTarget) return renderErrorPage(404, "Not Found", "この短縮URLは存在しません。");
  if (isLinkExpired(entryTarget.link)) return renderTerminalUnavailable(entryTarget.link.ended_message);
  if (isEntryExpired(entryTarget.entry!)) return renderTerminalUnavailable(entryTarget.entry!.ended_message);
  return entryTarget;
}
